  let sum = 0;
  let count = 0;
  let max = -Infinity;
  let current: number | null = null;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (typeof v !== 'number') continue;
    sum += v;
    count++;
    if (v > max) max = v;
    current = v;
  }
  return count ? {current, avg: sum / count, max} : {current: null, avg: null, max: null};
}

