(nohup npx vite --port 5199 --strictPort > /tmp/vite.log 2>&1 &) ; sleep 3; tail -5 /tmp/vite.log
cat > /tmp/pw/check1.mjs <<'EOF'
import {chromium} from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({viewport: {width: 1200, height: 800}});
const errs = [];
p.on('console', m => { if (['error','warning'].includes(m.type())) errs.push(m.type()+': '+m.text()); });
p.on('pageerror', e => errs.push('PAGEERROR: '+e.message));
await p.goto('http://localhost:5199/');
await p.waitForSelector('.cpu-chart__host canvas');
await p.waitForTimeout(800);
console.log('hosts', await p.locator('.cpu-chart__host').count(), 'canvases', await p.locator('canvas').count());
await p.screenshot({path: '/tmp/pw/light.png'});
const box = await p.locator('.cpu-chart__plot').boundingBox();
console.log('plot box', box);
await p.mouse.move(box.x + box.width*0.6, box.y + box.height*0.5);
await p.waitForTimeout(300);
console.log('tooltips', await p.locator('.yagr-tooltip').count(), JSON.stringify(await p.locator('.yagr-tooltip').allInnerTexts()));
await p.screenshot({path: '/tmp/pw/light-hover.png'});
// live updates
const s1 = await p.locator('.cpu-chart__stats').innerText();
await p.waitForTimeout(5000);
const s2 = await p.locator('.cpu-chart__stats').innerText();
console.log('stats before', JSON.stringify(s1), 'after', JSON.stringify(s2));
// dark
await p.getByText('Тёмная').click();
await p.waitForTimeout(500);
await p.mouse.move(box.x + box.width*0.3, box.y + box.height*0.5);
await p.waitForTimeout(300);
await p.screenshot({path: '/tmp/pw/dark-hover.png'});
console.log('tooltip class', await p.locator('.yagr-tooltip').first().getAttribute('class'));
// zoom by drag
await p.mouse.move(box.x + box.width*0.4, box.y + box.height*0.5);
await p.mouse.down(); await p.mouse.move(box.x + box.width*0.6, box.y + box.height*0.5, {steps: 8}); await p.mouse.up();
await p.waitForTimeout(500);
console.log('after zoom:', await p.locator('.cpu-chart__title').innerText(), 'resetDisabled', await p.getByText('Сбросить масштаб').isDisabled());
await p.screenshot({path: '/tmp/pw/dark-zoom.png'});
await p.waitForTimeout(4500); // live ticks while zoomed must not unzoom
console.log('still zoomed:', !(await p.getByText('Сбросить масштаб').isDisabled()));
await p.getByText('Сбросить масштаб').click();
await p.waitForTimeout(800);
console.log('after reset:', await p.locator('.cpu-chart__title').innerText(), 'resetDisabled', await p.getByText('Сбросить масштаб').isDisabled());
await p.screenshot({path: '/tmp/pw/dark-reset.png'});
// resize
await p.setViewportSize({width: 700, height: 600});
await p.waitForTimeout(600);
const b2 = await p.locator('.cpu-chart__plot').boundingBox();
const cw = await p.locator('.cpu-chart__host canvas').evaluate(c => c.getBoundingClientRect().width);
console.log('plot w after resize', b2.width, 'canvas css w', cw);
await p.screenshot({path: '/tmp/pw/narrow.png'});
console.log('ERRORS', JSON.stringify(errs, null, 1));
await b.close();
EOF
cd /tmp/pw && node check1.mjs

