import {createSimulatedCpuSource} from '/home/sandbox/workspace/src/cpu/cpuSource';
import {instances} from './yagr-rec';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const fails: string[] = [];
const check = (name: string, ok: boolean, extra?: unknown) => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra !== undefined ? '  ' + JSON.stringify(extra) : ''}`);
  if (!ok) fails.push(name);
};

const errors: string[] = [];
const origErr = console.error;
console.error = (...a: any[]) => { errors.push(a.map(String).join(' ').slice(0, 300)); };
process.on('uncaughtException', (e) => errors.push('UNCAUGHT ' + e.stack));

// учёт слушателей и таймеров
const listeners = new Map<string, number>();
for (const tgt of [window, document] as any[]) {
  const name = tgt === window ? 'window' : 'document';
  const add = tgt.addEventListener.bind(tgt), rem = tgt.removeEventListener.bind(tgt);
  tgt.addEventListener = (t: string, ...r: any[]) => { listeners.set(name + ':' + t, (listeners.get(name + ':' + t) ?? 0) + 1); return add(t, ...r); };
  tgt.removeEventListener = (t: string, ...r: any[]) => { listeners.set(name + ':' + t, (listeners.get(name + ':' + t) ?? 0) - 1); return rem(t, ...r); };
}
let intervals = 0;
const si = globalThis.setInterval, ci = globalThis.clearInterval;
(globalThis as any).setInterval = (...a: any[]) => { intervals++; return (si as any)(...a); };
(globalThis as any).clearInterval = (...a: any[]) => { intervals--; return (ci as any)(...a); };
const roObservers: any[] = (globalThis as any).__ro;

const N = 4000, STEP = 40;
const source = createSimulatedCpuSource({stepMs: STEP, windowMs: N * STEP});
const container = document.createElement('div');
document.body.appendChild(container);
const root = createRoot(container);
const render = (theme: 'light' | 'dark') =>
  act(async () => { root.render(<ThemeProvider theme={theme}><CpuLoadChart source={source} /></ThemeProvider>); });

const t0 = performance.now();
await render('light');
console.log('mount ms', Math.round(performance.now() - t0));
const chart = instances[instances.length - 1];
check('chart created', !!chart && instances.length >= 1, {instances: instances.length});
check('initial points', chart.uplot.data[0].length === N, chart.uplot.data[0].length);
check('one host + one u-wrap', container.querySelectorAll('.cpu-chart__host').length === 1 && container.querySelectorAll('.u-wrap').length === 1);

// --- живые обновления: окно скользит, длина постоянна
const firstT = chart.uplot.data[0][0];
await act(async () => { await sleep(900); });
const d = chart.uplot.data[0];
check('window length constant after live updates', d.length === N, d.length);
check('window slid forward', d[0] > firstT, {shifted: (d[0] - firstT) / STEP});
const hist = source.getHistory();
check('chart tail == source tail', d[d.length - 1] === hist.timeline[hist.timeline.length - 1] || hist.timeline[hist.timeline.length-1] - d[d.length-1] <= 2*STEP, {chart: d[d.length-1], src: hist.timeline[hist.timeline.length-1]});
const ys = chart.uplot.data[1];
check('series & timeline same length, strictly increasing',
  ys.length === d.length && d.every((v: number, i: number) => i === 0 || v > d[i - 1]));
check('config arrays in sync (no leak/growth)', chart.config.timeline.length === N && chart.config.series[0].data.length === N, [chart.config.timeline.length, chart.config.series[0].data.length]);
console.log('stats text:', container.querySelector('.cpu-chart__stats')!.textContent);

// --- тема
await render('dark');
check('theme class switched', chart.root.classList.contains('yagr_theme_dark') && !chart.root.classList.contains('yagr_theme_light'), chart.root.className);
check('series color switched', chart.config.series[0].color === '#3987e5', chart.config.series[0].color);
check('no chart re-creation on theme change', instances.length === 1 || instances.length === 2, instances.length);
const countAfterTheme = instances.length;

// --- зум: живые точки копятся, окно не сбрасывается
const len = N;
await act(async () => { const t = chart.uplot.data[0]; chart.uplot.setScale('x', {min: t[1000], max: t[2000]}); await sleep(50); });
const btn = () => [...container.querySelectorAll('button')].find((b) => b.textContent!.includes('Сбросить'))!;
check('zoom detected (reset enabled)', !btn().disabled);
const tailZoomed = chart.uplot.data[0][len - 1];
await act(async () => { await sleep(600); });
check('data frozen while zoomed', chart.uplot.data[0][len - 1] === tailZoomed && chart.uplot.scales.x.min > chart.uplot.data[0][0]);
await act(async () => { btn().click(); await sleep(150); });
check('reset enables live again', btn().disabled);
const dd = chart.uplot.data[0];
check('buffered points applied after reset', dd[dd.length - 1] > tailZoomed && dd.length === N, {caught_up_steps: (dd[dd.length-1]-tailZoomed)/STEP, len: dd.length});
check('x scale back to full range', chart.uplot.scales.x.min === dd[0] && chart.uplot.scales.x.max === dd[dd.length - 1]);

// --- ресайз
let rcalls = 0; const origReflow = chart.reflow.bind(chart); chart.reflow = (...a: any[]) => { rcalls++; return origReflow(...a); };
(HTMLElement.prototype as any).__w = 500;
await act(async () => { for (const ro of (globalThis as any).__ro) ro.fire(); await sleep(60); });
console.log('reflow calls after RO fire', rcalls);

// --- размонтирование
const before = {tooltips: document.querySelectorAll('.yagr-tooltip').length, intervals};
console.log('before unmount', JSON.stringify({...before, listeners: Object.fromEntries([...listeners].filter(([,v]) => v !== 0))}));
await act(async () => { root.unmount(); });
await act(async () => { for (const ro of (globalThis as any).__ro) ro.fire(); await sleep(300); });
check('DOM cleaned (no hosts, canvases, tooltips)', !document.querySelector('.cpu-chart__host, canvas, .u-wrap, .yagr-tooltip') && container.childElementCount === 0);
check('source timer stopped', intervals === 0, intervals);
check('all ResizeObservers disconnected', (globalThis as any).__ro.every((r: any) => r.disconnected));
const leaked = [...listeners].filter(([, v]) => v !== 0);
check('window/document listeners balanced', leaked.length === 0, leaked);
const real = errors.filter((e) => !/act\(|not wrapped|Warning/.test(e));
check('no console errors / uncaught exceptions', real.length === 0, real);
console.log(fails.length ? `\n${fails.length} FAILED: ${fails.join('; ')}` : '\nALL PASS');
process.exit(fails.length ? 1 : 0);
EOF
